  const markdownFiles = files.filter((f) => f.endsWith(".md"));
  // The TypeDoc sidebar carries the CSS section too (merged by @cssdoc/typedoc), so its labels cover
  // both the TS API and the CSS reference.
  const sidebarFiles = files.filter((f) => f.endsWith("typedoc-sidebar.json"));

  console.log(`🔄 ${locale}: translating...`);

  // 1. Markdown blocks
  const {
    glossaryTerms,
    proseBlocks,
    proseTranslated,
    proseCached,
  } = await translateMarkdownFiles(markdownFiles, adapter, memory, locale);

  console.log(
    `  📄 Markdown (${markdownFiles.length} file${markdownFiles.length === 1 ? "" : "s"}, ` +
      `${proseBlocks} prose block${proseBlocks === 1 ? "" : "s"}, ` +
      `${glossaryTerms} glossary term${glossaryTerms === 1 ? "" : "s"})`,
  );
  console.log(`    ✓ ${proseCached} cached, ${proseTranslated} translated`);

  // 2. Sidebar labels
  const {
    labelCount,
    labelTranslated,
    labelCached,
  } = await translateSidebars(sidebarFiles, adapter, memory, locale);

